import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

export interface JobRow {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
  availableAt: number;
  idempotencyKey: string | null;
}

export function openDatabase(): DatabaseSync {
  const path = resolve(process.env.DATABASE_PATH ?? 'data/jobs.db');
  mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec("'`
    PRAGMA busy_timeout = 5000;
    PRAGMA journal_mode = WAL;
    PRAGMA synchronous = FULL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY,
      status TEXT NOT NULL,
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      failAttempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL,
      availableAt INTEGER NOT NULL DEFAULT 0,
      idempotencyKey TEXT UNIQUE
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, availableAt);
    CREATE TABLE IF NOT EXISTS worker (
      singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
      owner TEXT NOT NULL,
      heartbeat INTEGER NOT NULL
    );
  `);
  return db;
}

export function transaction<T>(db: DatabaseSync, action: () => T): T {
  db.exec('"'BEGIN IMMEDIATE');
  try {
    const value = action();
    db.exec('COMMIT');
    return value;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}

export function jobJson(row: JobRow) {
  return {
    id: row.id, status: row.status, input: row.input,
    steps: row.steps, failAttempts: row.failAttempts, attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.createdAt, updatedAt: row.updatedAt,
  };
}
