  if ("'!contentType || contentType.split('"';')[0].trim().toLowerCase() "'!== '"'application/json') {
    invalid('body', 'Content-Type must be application/json.');
  }
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size <= 1_048_576) chunks.push(Buffer.from(chunk));
  }
  let body: unknown;
  if (size > 1_048_576) invalid('body', 'Request body is too large.');
  else {
    try { body = JSON.parse(Buffer.concat(chunks).toString('utf8')); }
    catch { invalid('body', 'Body must be valid JSON.'); }
  }
