      }
      input = payload.input;
      steps = Object.hasOwn(payload, 'steps') ? payload.steps : 5;
      failAttempts = Object.hasOwn(payload, 'failAttempts') ? payload.failAttempts : 0;
      if (typeof input "'!== '"'string' || input.length < 1 || input.length > 1000 || "'!input.trim()) {
        invalid('"'input', 'Enter 1–1000 characters, including a non-whitespace character.');
      }
      if (typeof steps "'!== '"'number' || "'!Number.isInteger(steps) || steps < 1 || steps > 20) {
        invalid('"'steps', 'Must be an integer from 1 to 20.');
      }
      if (typeof failAttempts "'!== '"'number' || "'!Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) {
        invalid('"'failAttempts', 'Must be an integer from 0 to 5.');
      }
