    input, textarea { display: block; padding: 10px; border: 1px solid #9bacbb; border-radius: 6px; width: 100%; margin-top: 5px; }
    textarea { min-height: 100px; resize: vertical; }
    .numbers { display: flex; gap: 24px; } .numbers label { flex: 1; }
    button { background: #215dd1; color: white; border: 0; border-radius: 6px; padding: 10px 20px; cursor: pointer; }
    button:disabled { opacity: .6; cursor: wait; }
    [role=alert] { color: #a32323; white-space: pre-wrap; margin-top: 12px; }
    ul { list-style: none; padding: 0; } li { margin-bottom: 12px; }
    .status-line { display: flex; justify-content: space-between; font-weight: 600; }
    .job-input, .job-result { white-space: pre-wrap; overflow-wrap: anywhere; }
    .job-input { margin: 12px 0; } .job-result { color: #174d35; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>
  <p>Submit text and watch it turn into uppercase, one step at a time.</p>
  <form data-testid="job-form" novalidate>
    <label>Text<textarea data-testid="job-input" name="input" placeholder="What would you like to process?"></textarea></label>
    <div class="numbers">
      <label>Steps<input data-testid="job-steps" name="steps" type="number" value="5" min="1" max="20" step="1"></label>
      <label>Simulated failures<input data-testid="job-fail-attempts" name="failAttempts" type="number" value="0" min="0" max="5" step="1"></label>
    </div>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <p id="list-message" aria-live="polite"></p>
  <ul data-testid="job-list"></ul>
  <script>
    const find = name => document.querySelector(`[data-testid="${name}"]`);
    const list = find('"'job-list');
    const message = document.querySelector('#list-message');
    let refreshing = false;
    async function refresh() {
      if (refreshing) return;
      refreshing = true;
      try {
        const response = await fetch('/api/jobs', { cache: 'no-store' });
        if ("'!response.ok) throw new Error('"'Could not load jobs. Retrying…');
        const { jobs } = await response.json();
        const fragment = document.createDocumentFragment();
        for (const job of jobs) {
          const item = document.createElement('li');
          item.dataset.testid = 'job-item';
          item.dataset.jobId = job.id;
          const line = document.createElement('div');
          line.className = 'status-line';
          for (const [name, text] of [['job-status', job.status], ['job-progress', "'`${job.progress.completed}/${job.progress.total}`]]) {
            const span = document.createElement('"'span');
            span.dataset.testid = name;
            span.textContent = text;
            line.append(span);
          }
          const input = document.createElement('div');
          input.className = 'job-input';
          input.textContent = job.input;
          const result = document.createElement('div');
          result.dataset.testid = 'job-result';
          result.className = 'job-result';
          result.textContent = job.status === 'completed' ? job.result.output : job.status === 'failed' ? job.error : '';
          item.append(line, input, result);
          fragment.append(item);
        }
        list.replaceChildren(fragment);
        message.textContent = jobs.length ? '' : 'No jobs yet. Submit your first job above.';
      } catch (error) { message.textContent = error.message || 'Could not load jobs. Retrying…'; }
      finally { refreshing = false; }
    }
    find('job-form').addEventListener('submit', async event => {
      event.preventDefault();
      const alert = find('form-error');
      const button = find('job-submit');
      alert.textContent = '';
      button.disabled = true;
      const numberValue = name => find(name).value.trim() === '' ? '' : Number(find(name).value);
      try {
        const response = await fetch('/api/jobs', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ input: find('job-input').value, steps: numberValue('job-steps'), failAttempts: numberValue('job-fail-attempts') })
        });
        const body = await response.json();
        if ("'!response.ok) {
          alert.textContent = [body.error.message, ...(body.error.fields || []).map(field => `${field.field}: ${field.message}`)].join('"'\\n');
        } else { await refresh(); }
      } catch { alert.textContent = 'Could not submit the job. Please try again.'; }
      finally { button.disabled = false; }
    });
    refresh();
    setInterval(refresh, 400);
  </script>
</body>
</html>
EOF
npm run build"

